110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
113	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
114	        if (normalizedTelephone == null) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        String normalizedAddress = Owner.normalizeAddress(ownerFieldsDto.getAddress());
118	        if (normalizedAddress == null || normalizedAddress.isBlank()) {
119	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
120	        }
121	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.CONFLICT);
123	        }
124	        if (isEmailAlreadyUsed(ownerFieldsDto.getEmail())) {
125	            return new ResponseEntity<>(HttpStatus.CONFLICT);
126	        }
127	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
128	            return new ResponseEntity<>(HttpStatus.CONFLICT);
129	        }
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	        LocalDate effectiveDate =
132	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
133	        LocalDate registrationDate = toBusinessDay(effectiveDate);
134	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
135	        if (ownersRegisteredToday >= 100) {
136	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
137	        }
138	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
139	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
140	        List<Owner> householdMembers =
141	            findHouseholdMembers(ownerFieldsDto.getLastName(), normalizedAddress);
142	        if (!sharesHousehold && !householdMembers.isEmpty()) {
143	            return new ResponseEntity<>(HttpStatus.CONFLICT);
144	        }
145	        HttpHeaders headers = new HttpHeaders();
146	        owner.setTelephone(normalizedTelephone);
147	        owner.setRegistrationDate(registrationDate);
148	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
149	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
150	        owner.setBulkSignupWarning(bulkSignupWarning);
151	        if (sharesHousehold && !householdMembers.isEmpty()) {
152	            String householdId = householdId(owner.getLastName(), normalizedAddress);
153	            owner.setHouseholdId(householdId);
154	            owner.setHouseholdSize(householdMembers.size() + 1);
155	            for (Owner member : householdMembers) {
156	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
157	                    member.setHouseholdId(householdId);
158	                    this.clinicService.saveOwner(member);
159	                }
160	            }
161	        }
162	        this.clinicService.saveOwner(owner);
163	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
164	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
165	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
166	        headers.setLocation(UriComponentsBuilder.newInstance()
167	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
168	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
169	    }
