241	    @Override
242	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
243	        HttpHeaders headers = new HttpHeaders();
244	        Visit visit = visitMapper.toVisit(visitFieldsDto);
245	        Pet pet = new Pet();
246	        pet.setId(petId);
247	        visit.setPet(pet);
248	        this.clinicService.saveVisit(visit);
249	        VisitDto visitDto = visitMapper.toVisitDto(visit);
250	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
251	            .buildAndExpand(visit.getId()).toUri());
252	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
253	    }
254	
255	
256	    /**
257	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
258	     * stripped. When a leading {@code '+'} and country code are present they are kept;
259	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
260	     * is dropped from the national digits. The result must be a {@code '+'} followed
261	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
262	     * is returned to signal a bad request.
263	     */
264	    /**
265	     * Build the customer code for a newly created owner, formatted
266	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
267	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
268	     * the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to
269	     * one more than the number of owners already in that city.
270	     */
271	    private String nextCustomerCode(String city, String lastName) {
272	        String cityPrefix = prefixThree(city);
273	        String lastNamePrefix = prefixThree(lastName);
274	        String normalizedCity = normalizeForHousehold(city);
275	        int sequence = (int) this.clinicService.findAllOwners().stream()
276	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
277	            .count() + 1;
278	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
279	    }
280	
281	    /**
282	     * Count the existing owners whose city matches the given one, compared after
283	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
284	     * cap: a city that already holds this many owners is at capacity.
285	     */
286	    private long countOwnersInCity(String city) {
287	        String normalizedCity = normalizeForHousehold(city);
288	        return this.clinicService.findAllOwners().stream()
289	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
290	            .count();
291	    }
292	
293	    /**
294	     * Count the existing owners whose registration date falls on the given day. Used to
295	     * enforce the per-day create limit: once this many owners have been registered today,
296	     * the day is at capacity and further creates are rejected.
297	     */
298	    private long countOwnersRegisteredOn(LocalDate day) {
299	        return this.clinicService.findAllOwners().stream()
300	            .filter(existing -> day.equals(existing.getRegistrationDate()))
301	            .count();
302	    }
303	
304	    /**
305	     * Roll a registration date forward to the next business day: a date falling on a
306	     * Saturday or Sunday is advanced to the following Monday, while a weekday is
307	     * returned unchanged.
308	     */
309	    private LocalDate toBusinessDay(LocalDate date) {
310	        DayOfWeek dayOfWeek = date.getDayOfWeek();
311	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
312	            return date.plusDays(8 - dayOfWeek.getValue());
313	        }
314	        return date;
315	    }
316	
317	    /** Upper-cased first three letters of {@code value} (fewer if shorter, empty if null). */
318	    private String prefixThree(String value) {
319	        String v = value == null ? "" : value;
320	        return v.substring(0, Math.min(3, v.length())).toUpperCase(Locale.ROOT);
321	    }
322	
323	    /**
324	     * Find the existing owners that already belong to the same household as the given
325	     * last name and address, i.e. those sharing both fields. Both are compared
326	     * case-insensitively after collapsing runs of whitespace to a single space and
327	     * trimming the ends.
328	     */
329	    private List<Owner> findHouseholdMembers(String lastName, String address) {
330	        String normalizedLastName = normalizeForHousehold(lastName);
331	        String normalizedAddress = normalizeForHousehold(address);
332	        return this.clinicService.findAllOwners().stream()
333	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
334	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
335	            .toList();
336	    }
337	
338	    /**
339	     * Count the existing owners that already share both the given first and last
340	     * name, compared case-insensitively. Used to populate an owner's namesake count
341	     * at creation time, reflecting how many owners with the same name existed before
342	     * this one was created.
343	     */
344	    private int countNamesakes(String firstName, String lastName) {
345	        String normalizedFirstName = normalizeName(firstName);
346	        String normalizedLastName = normalizeName(lastName);
347	        return (int) this.clinicService.findAllOwners().stream()
348	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
349	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
350	            .count();
351	    }
352	
